from h import *
R=[]
R.append((6177539,{
"es":L("Ensalada de ejotes a la parrilla","Los ejotes (judías verdes) recién salidos de la parrilla aportan un delicioso sabor asado a esta ensalada. Combinada con un aderezo sencillo y queso azul, seguro le encantará esta deliciosa ensalada de acompañamiento.","4","1 taza",
["1 libra de ejotes (judías verdes) frescos (sin las puntas)","1 cucharada de aceite de oliva","1 cucharadita de ajo en polvo","1/4 cucharadita de pimienta negra","2 cucharadas de vinagre balsámico","1 cucharada de mostaza Dijon","2 cucharadas + 1/4 taza de albahaca fresca (picada, dividida)","1 taza de tomates cherry (cortados por la mitad)","1/4 taza de queso azul (desmenuzado)"],
["Precaliente la parrilla o una sartén parrilla a fuego medio-alto.","En un tazón grande, mezcle los ejotes con el aceite de oliva, el ajo en polvo y la pimienta negra hasta que queden cubiertos de manera uniforme.","Coloque los ejotes sazonados en la parrilla precalentada. Áselos de 8 a 10 minutos, volteándolos de vez en cuando, o hasta que estén tiernos y tengan marcas de la parrilla.","Mientras los ejotes se asan, prepare el aderezo. En un tazón pequeño, bata el vinagre balsámico, la mostaza Dijon y 2 cucharadas de albahaca fresca picada. Agregue los tomates al aderezo.","Cuando los ejotes estén listos, páselos a una fuente para servir.","Vierta el aderezo y los tomates sobre la ensalada de ejotes.","Cubra con el queso azul desmenuzado y el resto de las hojas de albahaca."]),
"ar":L("سلطة الفاصوليا الخضراء المشوية","تضيف الفاصوليا الخضراء الخارجة لتوها من الشواية نكهة مشوية لذيذة إلى هذه السلطة. ومع تتبيلة بسيطة وجبن أزرق، ستحب بالتأكيد هذه السلطة الجانبية اللذيذة.","4","1 كوب",
["1 رطل فاصوليا خضراء طازجة (مقصوصة الأطراف)","1 ملعقة كبيرة زيت زيتون","1 ملعقة صغيرة مسحوق الثوم","¼ ملعقة صغيرة فلفل أسود","2 ملعقة كبيرة خل بلسميك","1 ملعقة كبيرة خردل ديجون","2 ملعقة كبيرة + ¼ كوب ريحان طازج (مفروم، مقسّم)","1 كوب طماطم كرزية (مقطعة نصفين)","¼ كوب جبن أزرق (مفتت)"],
["سخّن الشواية أو مقلاة الشواء على نار متوسطة إلى عالية.","في وعاء كبير، قلّب الفاصوليا الخضراء مع زيت الزيتون ومسحوق الثوم والفلفل الأسود حتى تتغطى بالتساوي.","ضع الفاصوليا المتبّلة على الشواية المسخّنة مسبقًا. اشوِها لمدة 8–10 دقائق مع قلبها من وقت لآخر، أو حتى تلين وتظهر عليها علامات الشواء.","بينما تُشوى الفاصوليا، حضّر التتبيلة. في وعاء صغير، اخفق خل البلسميك وخردل ديجون و2 ملعقة كبيرة من الريحان الطازج المفروم. أضف الطماطم إلى التتبيلة.","عندما تنضج الفاصوليا، انقلها إلى طبق تقديم.","اسكب التتبيلة والطماطم فوق سلطة الفاصوليا الخضراء.","غطِّها بالجبن الأزرق المفتت وباقي أوراق الريحان."])}))
R.append((6178564,{
"ar":L("سلطة الهليون المقشّر والفجل والبارميزان","هل لم تجرّب الهليون نيئًا من قبل؟ هذه فرصتك! جبن البارميزان وخردل ديجون اللاذع والليمون في هذه التتبيلة مرافق جريء للهليون المقطع شرائح رقيقة والفجل الحار.","4","1 كوب",
["6 حبات فجل صغيرة","2 ملعقة كبيرة جبن بارميزان (مبشور)","¼ ملعقة صغيرة فلفل أسود","1 فص ثوم (مبشور أو مفروم ناعمًا)","2 ملعقة كبيرة زيت زيتون","1 ملعقة كبيرة خردل ديجون","2 ملعقة كبيرة عصير ليمون (من 1 ليمونة متوسطة)","1 ملعقة كبيرة قشر ليمون مبشور (من 1 ليمونة متوسطة)","1 حزمة أعواد هليون كبيرة ((1 رطل))"],
["في وعاء سلطة كبير، اخفق قشر الليمون وعصير الليمون وخردل ديجون والثوم والفلفل الأسود المطحون وجبن البارميزان وزيت الزيتون.","اقطع الأطراف الخشبية من الهليون وتخلص منها. افصل رؤوس الهليون وقلّبها في الوعاء مع تتبيلة السلطة.","باستخدام مقشرة الخضار، قشّر سيقان الهليون طوليًا إلى شرائح وقلّبها مع التتبيلة في الوعاء (أو قطّع الهليون بشفرة التقطيع في محضّرة الطعام).","قشّر الفجل إلى شرائح باستخدام المقشرة أو المقطّعة أو شفرة التقطيع في محضّرة الطعام. قلّبه مع باقي مكونات السلطة."])}))
R.append((6178626,{
"ar":L("أقراص الكينوا","الكينوا بديل رائع للكسكس في معظم الوصفات. هذه الحبوب القديمة مشبعة ولذيذة ومصدر ممتاز للألياف. حضّر نسخًا صغيرة من أقراص الكينوا هذه لتكون مقبلات رائعة في الحفلات.","8","1 قرص",
["2 بخّة (0.50 غرام) بخاخ الطهي غير اللاصق (مقسّمة)","1 كوب كينوا (جافة)","2 كوب ماء","¼ كوب بصل أحمر (مفروم ناعمًا)","2 فص ثوم (مفروم ناعمًا)","1 علبة (15 أونصة) فاصوليا سوداء (مشطوفة ومصفّاة)","2 ملعقة كبيرة كزبرة خضراء (مفرومة ناعمًا، مقسّمة)","1 حبة جزر متوسطة (مبشورة (تعطي حوالي 1 كوب))","2 ملعقة كبيرة دقيق متعدد الاستخدامات","1 ملعقة صغيرة بيكنج باودر","1 بيضة كبيرة","1 بياض بيضة كبيرة","½ ملعقة صغيرة ملح (اختياري)","½ ملعقة صغيرة فلفل أسود","1 كوب زبادي يوناني سادة خالٍ من الدسم","2 ملعقة صغيرة عصير ليمون أخضر"],
["سخّن الفرن مسبقًا إلى 400° فهرنهايت (200° مئوية). ادهن صينية خبز كبيرة ببخاخ الطهي.","اطبخ الكينوا حسب تعليمات العبوة. فكّكها بالشوكة وضعها جانبًا لتبرد.","في وعاء كبير، اخلط الكينوا المطبوخة مع البصل والثوم والفاصوليا السوداء و1 ملعقة كبيرة من الكزبرة الخضراء والجزر والدقيق والبيكنج باودر والبيضة والملح (اختياري) والفلفل.","شكّل الخليط إلى ثمانية أقراص (اضغط بإحكام لتشكيل القرص) وضعها على الصينية المجهزة. رشّ وجه الأقراص ببخاخ الطهي.","اخبز الأقراص لمدة 15 دقيقة، ثم اقلبها. رشّها مرة أخرى ببخاخ الطهي. واصل الخبز 15 دقيقة أخرى أو حتى يصبح لونها بنيًا ذهبيًا فاتحًا.","بينما تُخبز الأقراص، اخلط باقي الكزبرة الخضراء والزبادي وعصير الليمون الأخضر في وعاء صغير. قدّم الصلصة مع أقراص الكينوا الدافئة."])}))
R.append((6178770,{
"es":L("Ensalada de hojas verdes mixtas y arándanos rojos","Colorida y festiva, esta ensalada fácil es perfecta para recibir invitados en días festivos. Puede cortar las verduras, separar los gajos de la naranja y preparar el aderezo con anticipación. Luego mezcle todo justo antes de servir.","8","1 taza",
["1 taza de arándanos rojos frescos (más aprox. 1/4 taza para decorar, si lo desea)","1 cucharada de endulzante sin azúcar","2 naranjas medianas","2 cucharadas de jugo de limón","2 tallos de apio (en rodajas finas)","1 cucharadita de jengibre fresco (rallado fino)","1 cucharadita de miel","1/2 cucharadita de mostaza Dijon","1/4 taza de aceite de oliva","1/4 cucharadita de sal marina","1/4 cucharadita de pimienta negra","5 tazas de hojas verdes mixtas","1/4 taza de cebolla morada (en rodajas muy finas)"],
["Ponga 1 taza de arándanos rojos en un procesador de alimentos y pulse unas cuantas veces para picarlos grueso, o píquelos a mano. En un tazón, mezcle los arándanos con el endulzante sin azúcar.","Pele las naranjas y sepárelas en gajos. Agregue las naranjas y el apio a los arándanos y mezcle suavemente; reserve.","Para el aderezo: en un tazón pequeño, bata el jugo de limón, el jengibre, la miel y la mostaza. Agregue lentamente el aceite en un chorro fino, batiendo para emulsionar. Incorpore batiendo la sal y la pimienta.","Mezcle las hojas verdes con 3/4 del aderezo. Coloque las hojas en una fuente poco profunda. Cubra las hojas con la mezcla de arándanos y naranja, la cebolla morada y, si lo desea, arándanos enteros para decorar. Rocíe con el aderezo restante."]),
"ar":L("سلطة الخضار الورقية المشكلة والتوت البري","هذه السلطة السهلة زاهية الألوان واحتفالية، وهي مثالية لاستقبال الضيوف في الأعياد. يمكنك تقطيع الخضار وتقسيم البرتقال إلى فصوص وتحضير التتبيلة مسبقًا. ثم اخلطها معًا قبل التقديم مباشرة.","8","1 كوب",
["1 كوب توت بري طازج (بالإضافة إلى ¼ كوب تقريبًا للتزيين إن رغبت)","1 ملعقة كبيرة محلٍّ خالٍ من السكر","2 حبة برتقال متوسطة","2 ملعقة كبيرة عصير ليمون","2 عود كرفس (مقطع شرائح رفيعة)","1 ملعقة صغيرة زنجبيل طازج (مبشور ناعمًا)","1 ملعقة صغيرة عسل","½ ملعقة صغيرة خردل ديجون","¼ كوب زيت زيتون","¼ ملعقة صغيرة ملح البحر","¼ ملعقة صغيرة فلفل أسود","5 كوب خضار ورقية مشكلة","¼ كوب بصل أحمر (مقطع شرائح رفيعة جدًا)"],
["ضع 1 كوب من التوت البري في محضّرة الطعام وشغّلها بنبضات قصيرة عدة مرات لتقطيعه تقطيعًا خشنًا، أو قطّعه باليد. في وعاء، قلّب التوت البري مع المحلي الخالي من السكر.","قشّر البرتقال وقسّمه إلى فصوص. أضف البرتقال والكرفس إلى التوت البري وقلّب برفق، ثم ضعه جانبًا.","للتتبيلة: في وعاء صغير، اخفق عصير الليمون والزنجبيل والعسل والخردل. أضف الزيت ببطء على شكل خيط رفيع مع الخفق لتكوين مستحلب. أضف الملح والفلفل مع الخفق.","قلّب الخضار الورقية مع ¾ التتبيلة. ضع الخضار في طبق تقديم مسطح. غطِّ الخضار بخليط التوت البري والبرتقال والبصل الأحمر، وبحبات التوت البري الكاملة للتزيين إن رغبت. رش عليها باقي التتبيلة."])}))
R.append((6180969,{
"ar":L("جزر صغير مع غموس الكريمة الحارة","غموس رائع بنكهة حارة قليلًا لوجبة خفيفة صحية.","4","2 ملعقة كبيرة من الغموس + 12 حبة جزر صغيرة",
["⅓ كوب كريمة حامضة (خالية من الدسم)","3 ملاعق كبيرة جبن كريمي قليل الدسم (علبة)","¾ ملعقة صغيرة صلصة الفلفل الحار","¼ ملعقة صغيرة ملح","48 حبة جزر صغير كاملة"],
["حرّك الكريمة الحامضة والجبن الكريمي وصلصة الفلفل والملح معًا حتى تمتزج جيدًا.","اتركه لمدة 10 دقائق على الأقل لتتطور النكهات وتخف حدتها قليلًا. قدّمه مع الجزر."])}))
R.append((6181016,{
"ar":L("دال العدس الأحمر مع \"رقائق\" الجيكاما","الدال يخنة عدس هندية سميكة تُقدَّم غالبًا مع خبز النان. يمكنك تقليل غرامات الكربوهيدرات بتقديم هذا الدال مع الجيكاما المقشرة والمقطعة شرائح. إنها خضار مقرمشة وحلوة قليلًا تشبه البطاطس.","12","⅓ كوب دال، 3 رقائق جيكاما".replace("یی","يي").replace("ما","ما"),
["1 ملعقة صغيرة زيت زيتون","1 حبة بصل صغيرة (مقطعة مكعبات)","2 فص ثوم (مفروم ناعمًا)","1 ملعقة كبيرة زنجبيل طازج (مبشور)","2 كوب عدس أحمر (جاف)","3½ كوب مرق خضار قليل الصوديوم","1 ملعقة كبيرة صلصة صويا (قليلة الصوديوم)","2 عود بصل أخضر (مفروم)","1 حبة جيكاما متوسطة".replace("یی","يي")],
["ضع زيت الزيتون في قدر على نار متوسطة. قلّب البصل والثوم والزنجبيل حتى يصبح البصل شفافًا (حوالي 4 دقائق).","أضف العدس وقلّبه ليتغطى بالزيت. أضف المرق وصلصة الصويا. اتركه حتى يغلي ثم اخفض الحرارة ليغلي بهدوء. دعه على نار هادئة والقدر مغطى لمدة 20 دقيقة.","اهرس العدس بخلاط يدوي أو محضّرة الطعام وأضف البصل الأخضر مع التحريك.","قشّر الجيكاما وقطّعها إلى تسعة أقراص. اقطع كل قرص إلى أربعة أرباع. استخدم الجيكاما النيئة لغمسها في الدال.".replace("یی","يي")])}))
R.append((6181063,{
"es":L("Puré de nabos","Pruebe nuestra vibrante receta de puré de nabos, un placer bajo en calorías lleno de vitaminas y antioxidantes, perfecto como acompañamiento rico en nutrientes.","5","aprox. 1/2 taza",
["4 nabos medianos (pelados y cortados en cubos)","1 cucharada de mantequilla (sin sal)","2 dientes de ajo (picados finamente)","1/3 taza de leche descremada","1/4 cucharadita de sal","1/2 cucharadita de pimienta negra"],
["Ponga agua en una cacerola grande y llévela a ebullición a fuego alto.","Agregue los nabos en cubos y hierva hasta que estén tiernos, unos 20 minutos.","Escurra y vuelva a poner los nabos en la olla.","Agregue la mantequilla, el ajo picado y la leche. Haga puré hasta que quede suave. Sazone con sal y pimienta."]),
"ar":L("هريس اللفت","جرّب وصفة هريس اللفت المفعمة بالحيوية، وهي متعة قليلة السعرات الحرارية مليئة بالفيتامينات ومضادات الأكسدة، ومثالية كطبق جانبي غني بالعناصر الغذائية.","5","حوالي ½ كوب",
["4 حبات لفت متوسطة (مقشرة ومقطعة مكعبات)","1 ملعقة كبيرة زبدة (غير مملحة)","2 فص ثوم (مفروم ناعمًا)","⅓ كوب حليب خالٍ من الدسم","¼ ملعقة صغيرة ملح","½ ملعقة صغيرة فلفل أسود"],
["ضع الماء في قدر كبير واتركه يغلي على نار عالية.","أضف مكعبات اللفت واسلقها حتى تلين، حوالي 20 دقيقة.","صفِّ اللفت وأعده إلى القدر.","أضف الزبدة والثوم المفروم والحليب. اهرسه حتى يصبح ناعمًا. تبّله بالملح والفلفل."])}))
R.append((6181283,{
"ar":L("سلطة البطاطس والقرنبيط","تقلل التتبيلة القائمة على الخل في سلطة البطاطس هذه من الدهون والسعرات الموجودة في سلطة البطاطس القائمة على المايونيز. كما استبدلنا القرنبيط بجزء من البطاطس لتقليل الكربوهيدرات وزيادة الألياف، مما يجعلها بديلًا صحيًا للقلب ومناسبًا لمرضى السكري عن سلطة البطاطس التقليدية.","8","½ كوب",
["1 بخّة (0.25 غرام) بخاخ الطهي غير اللاصق","4 كوب زهيرات قرنبيط (مقطعة تقطيعًا خشنًا)","5 حبات بطاطس حمراء متوسطة (مقطعة قطعًا بحجم 1 بوصة (تعادل 4 كوب مقطعة))","¼ كوب خل بلسميك","2 ملعقة كبيرة زيت زيتون","1 ملعقة صغيرة خردل ديجون","1 ملعقة كبيرة عسل","¼ كوب بقدونس طازج (مفروم)","¼ كوب بصل أحمر (مفروم ناعمًا)","1 حبة فلفل رومي أحمر متوسطة (منزوعة البذور ومقطعة مكعبات)"],
["سخّن الفرن مسبقًا إلى 375 درجة فهرنهايت (190° مئوية). ادهن صينية خبز ببخاخ الطهي.","رتّب القرنبيط والبطاطس في طبقة واحدة على الصينية وغطِّ الخضار ببخاخ الطهي. حمّصها لمدة 45 دقيقة حتى يصبح لون الخضار ذهبيًا مائلًا إلى البني وتلين.","في وعاء كبير، اخفق خل البلسميك وزيت الزيتون وخردل ديجون والعسل والبقدونس.","أضف البصل الأحمر والفلفل الرومي والبطاطس والقرنبيط الساخنين مباشرة من الفرن. قلّب جيدًا لتتغطى.","ضع السلطة في الثلاجة حتى تبرد (لمدة 1 ساعة على الأقل). قلّبها مرة أخرى قبل التقديم."])}))
R.append((6182435,{
"ar":L("طماطم كرزية محشوة بالجواكامولي","هذه الوصفة مقبلات أو وجبة خفيفة مثالية قليلة الكربوهيدرات. ولتقليل وقت التحضير أكثر، استخدم جواكامولي جاهزًا من المتجر لتحضير هذه الوصفة.","12","2 حبة طماطم",
["24 حبة طماطم كرزية كاملة (مستديرة، وليست طماطم عنبية)","1 حبة أفوكادو متوسطة (ناضجة)","1 حبة ليمون أخضر متوسطة (معصورة)","1 فص ثوم (مفروم ناعمًا أو مبشور)","2 ملعقة كبيرة كزبرة خضراء طازجة (مفرومة، مقسّمة)","½ ملعقة صغيرة ملح","½ ملعقة صغيرة فلفل أسود"],
["اقطع ساق كل حبة طماطم كرزية، مع القطع بعمق كافٍ لعمل فتحة في منتصف الطماطم دون الوصول إلى الطرف الآخر.","أفرغ داخل الطماطم بملعقة، وافرم الجزء الداخلي منها ناعمًا واحتفظ به للجواكامولي. ضع كل حبة طماطم مفرغة مقلوبة على مناديل ورقية لتصفية السوائل.","في وعاء متوسط، اهرس الأفوكادو بالشوكة واخلط معه قطع الطماطم المفرغة وعصير الليمون الأخضر والثوم و1 ملعقة كبيرة من الكزبرة الخضراء والملح (اختياري) والفلفل.","اغرف الجواكامولي أو اعصره بكيس تزيين في الطماطم المفرغة، مقسّمًا إياه بالتساوي بين الحبات. رشّ باقي الكزبرة الخضراء فوق كل حبة طماطم."])}))
R.append((6182454,{
"ar":L("سمك القد المغطى بالميسو","يتيح شيّ شرائح السمك وتحريك الخضار في المقلاة إعداد هذه الوجبة اللذيذة في 20 دقيقة وبسرعة كبيرة. قدّمها مع الأرز البني أو حبوب كاملة أخرى إن رغبت.","4","1 شريحة سمك + ¾ كوب خضار مقلية",
["1 بخّة (0.25 غرام) بخاخ الطهي غير اللاصق","1 رطل سمك أبيض (مثل سمك القد أو القاروس أو البرتقالي الخشن)","1 ملعقة كبيرة زيت سمسم محمص (مقسّمة)","1 ملعقة كبيرة مسحوق حساء الميسو الفوري (المسحوق فقط)","¼ ملعقة صغيرة فلفل أسود","4 كوب ملفوف نابا (مقطع شرائح)","2 فص ثوم (مبشور أو مفروم ناعمًا)","2 كوب بازلاء ثلجية (مقطعة)","1 ملعقة كبيرة صلصة حارة آسيوية"],
["سخّن الفرن على وضع الشواء (برويل). ضع رفًا في منتصف الفرن. ادهن صينية خبز ببخاخ الطهي.","قطّع السمك إلى 4 حصص، وزن كل منها 4 أونصات، ورتّبها على الصينية المجهزة.","في وعاء صغير، اخلط 1½ ملعقة صغيرة من زيت السمسم مع مسحوق حساء الميسو لتكوين معجون. افرد الطلاء على وجه كل شريحة سمك (ستكون الطبقة رقيقة جدًا). رشّ كل شريحة ببخاخ الطهي وضع الصينية على الرف الأوسط في الفرن. اشوِ لمدة 6 دقائق.","بينما يُشوى السمك، ضع باقي زيت السمسم (1½ ملعقة صغيرة) ومزيدًا من بخاخ الطهي في مقلاة ووك أو مقلاة كبيرة على نار عالية. حرّك الملفوف والثوم والبازلاء الثلجية والصلصة الحارة في المقلاة لمدة 4 دقائق، حتى تذبل قليلًا مع بقائها مقرمشة قليلًا.","أخرج السمك من الصينية وقدّمه فوق ¾ كوب من الخضار المقلية."])}))
R.append((6182531,{
"ar":L("ماسالا الحمّص (شانا)","الحمّص، أو الشانا، نوع قديم من البقوليات يُؤكل في الهند منذ قرون. تتوفر أنواع مختلفة من الحمّص، لكن النوع الأكثر استخدامًا هو البقوليات الشاحبة معتدلة النكهة المعروفة أيضًا باسم الحمّص الأبيض (غاربانزو). وفي الأسواق الهندية ستجد أيضًا الحمّص الأسود (أو كالا شانا)، وهو أغمق وأصغر من الحمّص العادي. شانا ماسالا طبق شائع جدًا في الهند والولايات المتحدة.\n\nهذه الوصفة من كتاب Indian Cuisine Diabetes Cookbook للمؤلفة May Abraham Fridel.","3","حوالي ⅔ كوب / 109 غرام",
["2 ملعقة كبيرة زيت عباد الشمس","½ ملعقة صغيرة بذور الكمون","قطعة زنجبيل طازج بطول 1 بوصة (مقشرة ومبشورة)","2 فص ثوم (مبشور)","1 حبة بصل أحمر متوسطة (مقطعة مكعبات صغيرة)","2 ملعقة صغيرة بابريكا مدخنة","2 ملعقة صغيرة مسحوق أمتشور (المانجو)","¼ ملعقة صغيرة كركم","1 ملعقة صغيرة كزبرة مطحونة","1 حبة طماطم متوسطة (مقطعة مكعبات صغيرة)","1 ملعقة كبيرة معجون طماطم","1 كوب ماء","1 علبة (15 أونصة) حمّص (مصفّى ومشطوف)","1 ملعقة كبيرة عصير ½ ليمونة","¼ ملعقة صغيرة ملح","1 ملعقة كبيرة كزبرة خضراء (مفرومة ناعمًا)"],
["سخّن الزيت في قدر ثقيل القاع على نار متوسطة إلى عالية وأضف بذور الكمون. عندما تبدأ البذور بالفرقعة، أضف الزنجبيل والثوم وقلّبهما لمدة 1 دقيقة. أضف البصل وقلّبه حتى يصبح بنيًا ذهبيًا، حوالي 2 دقيقة.","أضف البابريكا ومسحوق الأمتشور والكركم والكزبرة والطماطم ومعجون الطماطم إلى خليط البصل. اخفض الحرارة إلى متوسطة وقلّب باستمرار حتى يتماسك خليط الماسالا، حوالي 2 دقيقة.","أضف الحمّص وقلّبه ليتغطى بالماسالا. أضف 1 كوب / 240 مل من الماء وامزج جيدًا. اتركه على نار هادئة لمدة 20 دقيقة.","عندما تثخن الصلصة، ارفعه عن النار وأضف عصير الليمون والملح والكزبرة الخضراء. قدّمه ساخنًا."])}))
R.append((6183832,{
"es":L("Verduras de invierno asadas","Asar las raíces de invierno carameliza sus azúcares naturales y produce un sabor complejo, tostado y ligeramente dulce. Esta receta usa una variedad de verduras de invierno, pero puede usar cualquier combinación, siempre que obtenga unas 12 tazas en total de trozos del tamaño de un bocado. Esta receta se puede reducir fácilmente a la mitad si no cocina para mucha gente. Para agregar acidez, puede rociar ligeramente con vinagre balsámico justo antes de servir.","14","3/4 taza",
["2 tazas de zanahorias (peladas y cortadas en rodajas de 1 pulgada)","2 tazas de cebolla dulce (picada)","2 tazas de nabos (pelados y cortados en cubos de 1 1/2 pulgada)","2 tazas de chirivías (peladas y cortadas en rodajas de 1 pulgada de grosor)","2 tazas de rutabaga (pelada y cortada en cubos de 1 pulgada)","2 tazas de calabaza butternut (pelada y en cubos)","12 dientes de ajo (pelados)","2 cucharadas de aceite de oliva","1/2 cucharadita de sal","1 cucharada de tomillo fresco (picado finamente)","1/3 taza de perejil fresco (picado)"],
["Precaliente el horno a 400°F. En un tazón grande, combine todos los ingredientes, excepto el perejil y el tomillo.","Divida las verduras entre 2 bandejas grandes para hornear y extiéndalas en una sola capa en cada una. Ase las verduras de 45 a 60 minutos, volteándolas y revolviéndolas a la mitad del tiempo, hasta que estén tiernas y ligeramente doradas.","Pase las verduras a un tazón para servir y mezcle con el perejil y el tomillo."]),
"ar":L("خضار الشتاء المحمّصة","يؤدي تحميص جذور الخضار الشتوية إلى كرملة سكرياتها الطبيعية، مما ينتج نكهة معقدة ومحمصة وحلوة قليلًا. تتطلب هذه الوصفة مجموعة متنوعة من خضار الشتاء، لكن يمكنك استخدام أي مزيج منها، ما دام الناتج حوالي 12 كوب في المجموع من قطع بحجم اللقمة. ويمكن تقليل مقادير هذه الوصفة إلى النصف بسهولة إذا لم تكن تطبخ لعدد كبير. ولإضافة قليل من الحموضة، يمكنك رش خل البلسميك رشًا خفيفًا قبل التقديم مباشرة.","14","¾ كوب",
["2 كوب جزر (مقشر ومقطع أقراصًا بسمك 1 بوصة)","2 كوب بصل حلو (مفروم)","2 كوب لفت (مقشر ومقطع مكعبات بحجم 1½ بوصة)","2 كوب جزر أبيض (باستنك) (مقشر ومقطع أقراصًا بسمك 1 بوصة)","2 كوب لفت سويدي (روتاباغا) (مقشر ومقطع مكعبات بحجم 1 بوصة)","2 كوب قرع الجوز (مقشر ومقطع مكعبات)","12 فص ثوم (مقشر)","2 ملعقة كبيرة زيت زيتون","½ ملعقة صغيرة ملح","1 ملعقة كبيرة زعتر طازج (مفروم ناعمًا)","⅓ كوب بقدونس طازج (مفروم)"],
["سخّن الفرن مسبقًا إلى 400° فهرنهايت (200° مئوية). في وعاء كبير، اخلط جميع المكونات ما عدا البقدونس والزعتر.","وزّع الخضار على 2 صينية خبز كبيرة، وافردها في طبقة واحدة على كل صينية. حمّص الخضار لمدة 45 إلى 60 دقيقة، مع قلبها وتحريكها في منتصف المدة، حتى تلين ويصبح لونها بنيًا فاتحًا.","ضع الخضار في وعاء تقديم وأضف البقدونس والزعتر."])}))
R.append((6185607,{
"ar":L("يخنة اللحم البقري الكلاسيكية","لا تحتاج إلى طقس بارد للاستمتاع بيخنة لحم بقري رائعة. هناك الكثير من الوصفات الجديدة ليخنة اللحم، لكن إذا أتقنت هذه النسخة الكلاسيكية، فلن تحتاج إلى غيرها. ورغم إمكانية استخدام فطر الأزرار، حاول العثور على فطر كريميني لأن اليخنة ستكون ذات نكهة أغنى.","10","1 كوب",
["2 ملعقة كبيرة دقيق متعدد الاستخدامات أو دقيق القمح الكامل للمعجنات","1 ملعقة كبيرة توابل إيطالية","3 ملاعق كبيرة زيت زيتون","2 رطل لحم فخذ بقري (مقطع مكعبات بحجم ¾ بوصة)","1½ رطل فطر كريميني (بيبي بيلا) (منظف ومنزوع السيقان ومقطع أرباعًا)","4 كوب مرق دجاج قليل الصوديوم (منخفض الصوديوم وقليل الدسم، مقسّم)","1 حبة بصل كبيرة (مفرومة خشنًا)","3 فص ثوم (مفروم ناعمًا)","2 حبة بطاطس روسيت كبيرة","3 حبات جزر متوسطة (مقشرة)","1 كوب بازلاء مجمدة","1 ملعقة كبيرة زعتر طازج (مفروم ناعمًا)","1 ملعقة كبيرة خل النبيذ الأحمر","½ ملعقة صغيرة فلفل أسود مطحون طازجًا (¼–½ ملعقة صغيرة)"],
["اخلط الدقيق متعدد الاستخدامات مع التوابل الإيطالية. سخّن زيت الزيتون في قدر هولندي كبير على نار متوسطة. غطِّ مكعبات اللحم تغطية خفيفة بخليط الدقيق وأضفها إلى القدر على دفعات بحيث تبقى في طبقة واحدة، حتى تتحمر جيدًا من كل جانب.","أخرج اللحم من القدر وأضف ¼ كوب من مرق الدجاج لإذابة الرواسب من قاع القدر. أضف الفطر وقلّبه لمدة 4 دقائق تقريبًا حتى يتحمر جيدًا. أخرج الفطر من القدر وأضف ¼ كوب آخر من المرق لإذابة الرواسب. أضف البصل والثوم وقلّبهما لمدة 4 دقائق. أعد اللحم إلى القدر، وأضف باقي مرق الدجاج، واتركه حتى يغلي. غطِّ القدر جزئيًا، وخفّض النار ليغلي بهدوء، واطهِه لمدة 45 دقيقة مع التحريك من وقت لآخر.","قشّر البطاطس وقطّعها إلى قطع بحجم ¾ بوصة. قطّع الجزر إلى قطع بحجم ½ بوصة. أضف البطاطس والجزر إلى اليخنة وواصل الطهي 45 دقيقة أخرى أو حتى تلين الخضار. أضف الفطر المحتفظ به والبازلاء والزعتر. تبّلها بخل النبيذ الأحمر والفلفل الأسود."])}))
save(3,R)
